def create_default_permissions(apps, schema_editor):
    Course = apps.get_model("courses", "course")
    CourseStaffPermission = apps.get_model("courses", "coursestaffpermission")

    for course in Course.objects.all():
        try:
            responsible = course.main_responsible
        except:
            print(f"    Can't find responsible for course {course.slug}")
            continue

        if responsible is None:
            print(f"    Responsible for {course.slug} is not set")
            continue

        for instance in course.courseinstance_set.get_queryset():
            if not CourseStaffPermission.objects.filter(
                user=responsible,
                instance=instance,
            ).exists:
                permission = CourseStaffPermission(
                    user=responsible,
                    instance=instance,
                    start_time=datetime.datetime.now(),
                )
                permission.permit_all()
                permission.save()


